\title{Categorification of Entropy: The Information Loss of a Functor}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We quantify the information that a functor loses when it identifies distinct objects.
Working with functors between finite categories---equivalently, with the map they induce
on finite sets of objects---we define the \emph{functorial entropy} $H(F)$ as the
conditional entropy of a uniformly random domain object given its image. Concretely, if
$c_d$ denotes the cardinality of the fiber of $F$ over a target object $d$ and $n$ is the
number of objects in the domain, then
\[
  H(F) = \sum_{d} \frac{c_d}{n}\,\log c_d.
\]
We prove six structural theorems: nonnegativity; vanishing exactly on functors injective
on objects; the value $\log k = \log(|\Ob C|/|\Ob D|)$ for uniform fibers of size $k$; the
value $\log n$ for a constant functor; the upper bound $H(F)\le \log n$; and a
\emph{data-processing inequality} $H(f)\le H(g\circ f)$. We situate these against classical
Shannon theory, work through motivating examples, and outline extensions.
\end{abstract}

\maketitle

\section{Introduction}

Shannon entropy measures the uncertainty of a random variable $X$ taking value $x$ with
probability $p(x)$:
\[
  H(X) = -\sum_x p(x)\log p(x).
\]
Category theory offers a language for structure-preserving translation via \emph{functors}
$F : C \to D$. A recurring informal theme is that a functor ``loses information'' when it
maps non-isomorphic objects to isomorphic ones---the paradigm being a \emph{forgetful
functor}. The qualitative counterpart is \emph{faithfulness}. This paper makes the metaphor
quantitative: to each functor between finite categories we assign a real number
$H(F)\ge 0$, its information loss, and prove it behaves as an information-theoretic measure
of forgetting should. The construction is a \emph{categorification} of entropy: a
combinatorial/probabilistic quantity recovered as an invariant of a morphism.

\subsection{The naive marginal entropy is wrong}
Pushing the uniform distribution on $\Ob C$ forward along $F$ and taking the Shannon
entropy of the image distribution,
$H_{\mathrm{marg}}(F) = -\sum_d p(d)\log p(d)$ with $p(d)=c_d/n$, is unsuitable: an injective
functor into an $m$-object target already has marginal entropy $\log m>0$ despite forgetting
nothing. The marginal entropy measures the spread of the image, not the loss along the way.

\subsection{Conditional entropy is right}
Given that the image is $d$, the domain object is uniform over the $c_d$ objects of the
fiber, so the residual uncertainty is $\log c_d$; averaging over $p(d)=c_d/n$ gives
\begin{equation}\label{eq:def}
  H(F) = \sum_d \frac{c_d}{n}\,\log c_d,
\end{equation}
the conditional entropy $H(C\mid F(C))$. This is the definition we study.

\section{Setup and definitions}

We model a functor between finite categories by the function it induces on object sets.
Write $\alpha=\Ob C$ and $\beta=\Ob D$, both finite, with $n=|\alpha|\ge 1$.

\begin{definition}[Fiber cardinality]
For $F:\alpha\to\beta$ and $d\in\beta$, the \emph{fiber cardinality} is
$c_d := |\{a\in\alpha : F(a)=d\}| = |F^{-1}(d)|$.
\end{definition}

\begin{lemma}[Fiber partition]\label{lem:part}
$\sum_{d\in\beta} c_d = |\alpha| = n$.
\end{lemma}
\begin{proof}
The sets $F^{-1}(d)$ are pairwise disjoint and cover $\alpha$; summing cardinalities counts
each element once.
\end{proof}

\begin{definition}[Functorial entropy]
The \emph{functorial entropy}, or \emph{information loss}, of $F:\alpha\to\beta$ is
\[
  H(F) := \sum_{d\in\beta} \frac{c_d}{n}\,\log c_d,
\]
with the convention that the summand vanishes when $c_d=0$. Here $\log$ is the natural
logarithm; changing base rescales $H$ by a positive constant.
\end{definition}

Probabilistically, $H(F)$ is the conditional entropy $H(A\mid F(A))$ where $A$ is uniform
on $\alpha$.

\section{Main results}

Throughout, $F:\alpha\to\beta$ is a function between finite sets with $|\alpha|=n\ge 1$.

\begin{theorem}[Loss is nonnegative]
$H(F)\ge 0$.
\end{theorem}
\begin{proof}
Each summand is a product of the nonnegative weight $c_d/n$ and $\log c_d\ge 0$ (as $c_d$ is
a nonnegative integer, either $c_d=0$ and the term vanishes, or $c_d\ge 1$ and
$\log c_d\ge 0$). A sum of nonnegative terms is nonnegative.
\end{proof}

\begin{lemma}[Injectivity via fibers]\label{lem:inj}
$F$ is injective if and only if $c_d\le 1$ for every $d\in\beta$.
\end{lemma}
\begin{proof}
If $F$ is injective, no two elements share an image, so each fiber has at most one element.
Conversely, a collision $x\ne y$ with $F(x)=F(y)$ would force $c_{F(x)}\ge 2$; the hypothesis
forbids this, giving injectivity.
\end{proof}

\begin{theorem}[Vanishing criterion]
$H(F)=0$ if and only if $F$ is injective on objects.
\end{theorem}
\begin{proof}
The sum \eqref{eq:def} has nonnegative terms, so it is zero iff every term is zero. The term
for $d$ vanishes iff $c_d\in\{0,1\}$, i.e.\ $c_d\le 1$. By Lemma~\ref{lem:inj} this holds for
all $d$ iff $F$ is injective.
\end{proof}

\begin{theorem}[Uniform fibers]
If $c_d=k$ for all $d\in\beta$, then $H(F)=\log k$. If moreover $F$ is surjective (so
$|\beta|=m$ and no fiber is empty), then $n=mk$ and
$H(F)=\log k = \log(n/m)=\log(|\Ob C|/|\Ob D|)$.
\end{theorem}
\begin{proof}
Substituting $c_d=k$ in \eqref{eq:def} gives
$H(F)=\sum_{d}\frac{k}{n}\log k = \frac{mk}{n}\log k$. By Lemma~\ref{lem:part},
$mk=\sum_d c_d = n$, so the prefactor is $1$ and $H(F)=\log k$. Surjectivity with $k\ge1$
rearranges $n=mk$ to $k=n/m$; $k=0$ is impossible since $n\ge1$.
\end{proof}

\begin{theorem}[Constant functor]
If $F(a)=d_0$ for all $a$, then $H(F)=\log n$.
\end{theorem}
\begin{proof}
The only nonempty fiber is over $d_0$ with $c_{d_0}=n$, so \eqref{eq:def} collapses to
$\frac{n}{n}\log n=\log n$.
\end{proof}

\begin{theorem}[Maximum-loss bound]
For every $F$, $\ H(F)\le \log n$.
\end{theorem}
\begin{proof}
For each $d$, monotonicity of $\log$ and $c_d\le n$ give $\log c_d\le\log n$ when $c_d\ge1$
(and the term vanishes when $c_d=0$); thus $\frac{c_d}{n}\log c_d\le\frac{c_d}{n}\log n$.
Summing and using Lemma~\ref{lem:part},
$H(F)\le \frac{\log n}{n}\sum_d c_d = \log n$.
\end{proof}

\begin{lemma}[Fibers of a composite]\label{lem:comp}
Let $f:\alpha\to\beta$, $g:\beta\to\gamma$ with $\gamma$ finite. For $e\in\gamma$,
\[
  c^{g\circ f}_e = \sum_{d:\,g(d)=e} c^{f}_d .
\]
\end{lemma}
\begin{proof}
$a\in\alpha$ satisfies $g(f(a))=e$ iff $f(a)=d$ for the unique $d$ with $g(d)=e$; hence
$(g\circ f)^{-1}(e)$ is the disjoint union of $f^{-1}(d)$ over such $d$, and cardinalities
add.
\end{proof}

\begin{theorem}[Data-processing inequality]
For $f:\alpha\to\beta$, $g:\beta\to\gamma$ finite with $n=|\alpha|\ge1$,
\[
  H(f)\le H(g\circ f).
\]
\end{theorem}
\begin{proof}
Group the domain by its $f$-fiber. For each $e\in\gamma$, Lemma~\ref{lem:comp} gives
$c^{g\circ f}_e=\sum_{g(d)=e}c^f_d$, so $c^f_d\le c^{g\circ f}_e$ for each such $d$, and by
monotonicity of $\log$,
\[
  \sum_{g(d)=e} c^f_d\log c^f_d \;\le\; \sum_{g(d)=e} c^f_d\log c^{g\circ f}_e
  \;=\; c^{g\circ f}_e\log c^{g\circ f}_e.
\]
Dividing by $n$ and summing over $e\in\gamma$ yields $H(f)\le H(g\circ f)$.
\end{proof}

\section{Worked examples}

\begin{example}[Inclusion of finite groups]
The inclusion of finite groups into all groups sends each finite group to itself; it is
injective on objects, so $H=0$: no information is lost.
\end{example}

\begin{example}[Abelianization]
The abelianization functor sends a group to its largest abelian quotient. Distinct groups
can share an abelianization. On finite models where each abelian object receives a small,
roughly two-element family of preimages, the uniform-fiber formula gives a loss of order
$\log 2$---one bit.
\end{example}

\begin{example}[Forgetful functor to sets]
Discarding the topology of a space records only its underlying point set. Over an infinite
set there are uncountably many topologies, so the fibers are infinite and $H\to\infty$: a
functor identifying infinitely many non-isomorphic objects has infinite entropy.
\end{example}

\section{Discussion and future directions}

The functorial entropy converts faithfulness/forgetfulness into a quantitative invariant,
and the six theorems show it behaves as an information measure ought to. The
data-processing inequality is the structural heart and mirrors its classical namesake.
Natural extensions include: (1) a chain rule $H(g\circ f)=H(f)+H_f(g)$; (2) weighted priors
recovering full Shannon conditional entropy; (3) a morphism-level entropy weighting hom-set
collapse; (4) an infinite theory realizing $H=\infty$ for the forgetful functor to sets;
(5) study of $F\mapsto H(F)$ under products and coproducts; and (6) comparison with the
magnitude and Baez--Fritz--Leinster characterizations of entropy.

\section{Conclusion}

Every functor casts an information-theoretic shadow. Defining $H(F)$ as the conditional
entropy of a domain object given its image yields a computable, nonnegative invariant that
vanishes exactly on faithful functors, has a clean closed form for uniform fibers, is
maximized by constant functors, is bounded by the domain's total information, and satisfies
a data-processing inequality. Entropy is the information-theoretic shadow of functoriality
itself.

\end{document}

