"""Demo: verifying the uniform-fiber formula H(F) = log k = log(n/m)."""
from __future__ import annotations
import math
from collections import Counter
from typing import Hashable, Sequence


def functorial_entropy(images: Sequence[Hashable], base: float = 2.0) -> float:
    n = len(images)
    if n == 0:
        return 0.0
    return sum((c / n) * math.log(c, base)
               for c in Counter(images).values() if c > 0)


def check_uniform(k: int, m: int) -> tuple[float, float, float]:
    """Build a surjective k-to-one functor onto m targets and compare
    H(F) with log2(k) and log2(n/m)."""
    images = [d for d in range(m) for _ in range(k)]
    n = k * m
    return functorial_entropy(images), math.log2(k), math.log2(n / m)


if __name__ == "__main__":
    for k, m in [(2, 3), (4, 2), (5, 5), (3, 7)]:
        H, lk, lnm = check_uniform(k, m)
        print(f"k={k}, m={m}:  H={H:.4f}  log2(k)={lk:.4f}  log2(n/m)={lnm:.4f}")

"""Demo: Monte-Carlo confirmation of the data-processing inequality
H(f) <= H(g o f) over random functors between finite object sets."""
from __future__ import annotations
import math
import random
from collections import Counter
from typing import Hashable, Sequence


def functorial_entropy(images: Sequence[Hashable], base: float = 2.0) -> float:
    n = len(images)
    if n == 0:
        return 0.0
    return sum((c / n) * math.log(c, base)
               for c in Counter(images).values() if c > 0)


def trial(n: int, size_b: int, size_c: int, rng: random.Random) -> tuple[float, float]:
    f = {a: rng.randrange(size_b) for a in range(n)}
    g = {b: rng.randrange(size_c) for b in range(size_b)}
    Hf = functorial_entropy([f[a] for a in range(n)])
    Hgf = functorial_entropy([g[f[a]] for a in range(n)])
    return Hf, Hgf


if __name__ == "__main__":
    rng = random.Random(2024)
    worst = 0.0
    for _ in range(100000):
        Hf, Hgf = trial(16, 6, 3, rng)
        worst = max(worst, Hf - Hgf)      # should stay <= 0
    print(f"max observed H(f) - H(g o f) over 100k trials: {worst:.6f}  (<= 0 confirms DPI)")

